import React, { useState } from 'react';

const SECTORS = [
  "Small and Medium Enterprises (SMEs)",
  "Large Enterprises",
  "Finance and Insurance",
  "Healthcare and Pharmaceuticals",
  "Public Sector and Government",
  "Critical Infrastructure",
  "Energy and Utilities",
  "Transportation and Logistics",
  "Telecommunications",
  "Information Technology and Software",
  "Cloud and SaaS Providers",
  "Manufacturing and Industry",
  "Education and Research",
  "Retail and E-Commerce",
  "Construction and Real Estate",
  "Legal and Consulting Services",
  "Media and Entertainment",
  "Agriculture and Food",
  "Defense and Aerospace",
  "Non-Profit and NGOs"
];

interface LoginProps {
  onLogin: (username: string, sector: string) => void;
}

// Gemini API mock (replace with real API call)
async function getSectorFromJob(job: string): Promise<string> {
  // TODO: Replace with real Gemini API call
  // For now, return a random sector for demo
  // In production, use fetch or axios to call your backend or Gemini API
  // and map the result to one of the SECTORS
  return new Promise((resolve) => {
    setTimeout(() => {
      // Simple keyword matching for demo
      const lower = job.toLowerCase();
      const found = SECTORS.find(s => s.toLowerCase().includes(lower.split(' ')[0]));
      resolve(found || "Education and Research");
    }, 1200);
  });
}

const sectorInfo =
  "Sektör seçimi, değerlendirme sorularının ve analizlerin size uygun şekilde sunulmasını sağlar. Lütfen çalıştığınız sektörü seçin veya arayın. Eğer bulamazsanız, 'My job is not listed' ile kendi işinizi girin.";

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [sector, setSector] = useState(SECTORS[0]);
  const [search, setSearch] = useState('');
  const [showCustomJob, setShowCustomJob] = useState(false);
  const [customJob, setCustomJob] = useState('');
  const [isLoadingSector, setIsLoadingSector] = useState(false);
  const [customError, setCustomError] = useState('');
  const [showInfo, setShowInfo] = useState(false);

  const filteredSectors = SECTORS.filter(s =>
    s.toLowerCase().includes(search.toLowerCase())
  );

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!username.trim()) return;
    if (showCustomJob) {
      if (!customJob.trim()) {
        setCustomError('Please enter your job title.');
        return;
      }
      setCustomError('');
      setIsLoadingSector(true);
      // Call Gemini API to get sector
      const suggestedSector = await getSectorFromJob(customJob.trim());
      setIsLoadingSector(false);
      onLogin(username.trim(), suggestedSector);
    } else {
      onLogin(username.trim(), sector);
    }
  };

  return (
    <div className="flex items-center justify-center min-h-screen bg-[#0f0f23]">
      <form onSubmit={handleSubmit} className="bg-[#1e1e3f] p-8 rounded-lg shadow-lg w-full max-w-md flex flex-col gap-6">
        <h2 className="text-2xl font-bold text-blue-400 mb-2 text-center">Welcome</h2>
        <div>
          <label className="block text-gray-300 mb-2" htmlFor="username">Username</label>
          <input
            id="username"
            type="text"
            className="w-full p-3 rounded bg-[#0f0f23] border border-gray-700 text-gray-100 focus:outline-none focus:border-blue-500"
            value={username}
            onChange={e => setUsername(e.target.value)}
            required
            autoFocus
          />
        </div>
        <div>
          <div className="flex items-center mb-2">
            <label className="block text-gray-300 mr-2" htmlFor="sector">Sector</label>
            <button
              type="button"
              className="ml-1 text-blue-400 hover:text-blue-200 relative"
              onMouseEnter={() => setShowInfo(true)}
              onMouseLeave={() => setShowInfo(false)}
              tabIndex={-1}
            >
              <svg width="18" height="18" fill="currentColor" viewBox="0 0 20 20"><circle cx="10" cy="10" r="9" stroke="currentColor" strokeWidth="2" fill="none"/><text x="10" y="15" textAnchor="middle" fontSize="12" fill="currentColor">i</text></svg>
              {showInfo && (
                <span className="absolute left-6 top-0 z-10 w-64 bg-gray-900 text-gray-200 text-xs rounded-lg p-3 shadow-lg border border-blue-400">
                  {sectorInfo}
                </span>
              )}
            </button>
          </div>
          {!showCustomJob && (
            <>
              <input
                type="text"
                placeholder="Search sector..."
                className="w-full mb-2 p-2 rounded bg-[#0f0f23] border border-gray-700 text-gray-100 focus:outline-none focus:border-blue-500"
                value={search}
                onChange={e => setSearch(e.target.value)}
              />
              <select
                id="sector"
                className="w-full p-3 rounded bg-[#0f0f23] border border-gray-700 text-gray-100 focus:outline-none focus:border-blue-500"
                value={sector}
                onChange={e => setSector(e.target.value)}
                size={Math.min(filteredSectors.length, 6)}
              >
                {filteredSectors.map(s => (
                  <option key={s} value={s}>{s}</option>
                ))}
              </select>
              <button
                type="button"
                className="mt-2 w-full text-blue-400 hover:underline text-sm"
                onClick={() => setShowCustomJob(true)}
              >
                My job is not listed
              </button>
            </>
          )}
          {showCustomJob && (
            <div className="mt-2 flex flex-col gap-2">
              <textarea
                className="w-full p-3 rounded bg-[#0f0f23] border border-gray-700 text-gray-100 focus:outline-none focus:border-blue-500"
                placeholder="Please describe your job title or field..."
                value={customJob}
                onChange={e => setCustomJob(e.target.value)}
                rows={2}
                required
              />
              {customError && <span className="text-red-400 text-xs">{customError}</span>}
              <button
                type="button"
                className="text-blue-400 hover:underline text-sm self-start"
                onClick={() => { setShowCustomJob(false); setCustomJob(''); setCustomError(''); }}
              >
                Back to sector list
              </button>
            </div>
          )}
        </div>
        <button
          type="submit"
          className="bg-blue-600 text-white font-medium rounded-lg px-5 py-3 transition hover:bg-blue-700 disabled:bg-gray-500 disabled:cursor-not-allowed flex items-center justify-center"
          disabled={!username.trim() || (showCustomJob && (!customJob.trim() || isLoadingSector))}
        >
          {isLoadingSector ? (
            <svg className="animate-spin h-5 w-5 mr-2 text-white" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none" /><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" /></svg>
          ) : null}
          {showCustomJob ? 'Continue' : 'Enter'}
        </button>
      </form>
    </div>
  );
};

export default Login;
